/**
 * Drift-list ranking tests.
 *
 * Co-change is a RANKED signal, not a set. A file that changes alongside every
 * commit (CI config, lint config, ignore files) carries no information about
 * the symbol under change, and a long warning list buries the row that matters.
 *
 * The filter is presentation only: everything stays in `allowed_files`, so
 * editing a suppressed file is never penalised, and everything suppressed is
 * disclosed in `degraded[]`. Hiding evidence silently would be the same class
 * of failure this product exists to catch.
 */
import { test } from "node:test";
import assert from "node:assert/strict";

import { buildContract, coChangeStrength, isRepoPlumbing } from "./build.js";
import { DEFAULT_POLICY, type Provenance } from "../types.js";
import type { GraphEdge, ImpactResult } from "../evidence/graph.js";

const PROV: Provenance = {
  source: "graph.impact",
  command: "entire graph impact --symbol Target --repo . --depth 2 --profile full --format json",
  confidence: "deterministic",
};

function coChange(path: string, commits: number): GraphEdge {
  return {
    endpoint: { id: `local:file:${path}`, name: path, kind: "file", file_path: path },
    relation: "FILE_CHANGES_WITH",
    detail: `files changed together in ${commits} recent commits`,
  };
}

function impactWith(entries: GraphEdge[]): ImpactResult {
  return {
    format_version: 1,
    repo_root: "/repo",
    commit: "aaa",
    profile: "full",
    query: "Target",
    depth: 2,
    focus_matches_total: 1,
    focus: {
      id: "local:Go:src/target.go:function:Target",
      name: "Target",
      kind: "function",
      file_path: "src/target.go",
      start_line: 10,
      language: "Go",
    },
    co_changes: { total: entries.length, entries },
  };
}

function build(entries: GraphEdge[], policy = DEFAULT_POLICY) {
  return buildContract({
    id: "ct-drift",
    repoRoot: "/repo",
    baseSha: "aaa",
    symbol: "Target",
    impact: impactWith(entries),
    impactProvenance: PROV,
    policy,
    degraded: [],
  });
}

test("repo plumbing is recognised, real source is not", () => {
  for (const p of [
    ".github/workflows/ci.yml",
    ".github/workflows/lint.yml",
    ".gitignore",
    ".golangci.yaml",
    "mise.toml",
    "LICENSE",
    "package-lock.json",
  ]) {
    assert.equal(isRepoPlumbing(p), true, `${p} should be plumbing`);
  }
  for (const p of [
    "agents/entire-agent-kiro/internal/protocol/protocol.go",
    "src/target.go",
    "internal/kiro/agent.go",
  ]) {
    assert.equal(isRepoPlumbing(p), false, `${p} should NOT be plumbing`);
  }
});

test("co-change strength parses the commit count, and degrades to 0", () => {
  assert.equal(coChangeStrength("files changed together in 4 recent commits"), 4);
  assert.equal(coChangeStrength("files changed together in 1 recent commit"), 1);
  assert.equal(coChangeStrength(undefined), 0);
  assert.equal(coChangeStrength("FILE_CHANGES_WITH"), 0);
});

test("plumbing is excluded from drift warnings but stays editable", () => {
  const c = build([
    coChange(".github/workflows/ci.yml", 9),
    coChange(".gitignore", 9),
    coChange("internal/kiro/agent.go", 5),
  ]);
  assert.deepEqual(c.drift_candidates.map((d) => d.path), ["internal/kiro/agent.go"]);
  // Critically: still permitted to edit, so no FAIL for touching them.
  const allowed = c.allowed_files.map((f) => f.path);
  assert.ok(allowed.includes(".github/workflows/ci.yml"));
  assert.ok(allowed.includes(".gitignore"));
  // And the suppression is disclosed, not silent.
  assert.ok(c.degraded.some((d) => /repository plumbing/.test(d)));
});

test("drift is ranked strongest-first and capped, with the remainder disclosed", () => {
  const c = build(
    [
      coChange("a.go", 2),
      coChange("b.go", 9),
      coChange("c.go", 5),
      coChange("d.go", 7),
    ],
    { ...DEFAULT_POLICY, drift_max: 2 },
  );
  assert.deepEqual(c.drift_candidates.map((d) => d.path), ["b.go", "d.go"]);
  assert.ok(
    c.degraded.some((d) => /2 further co-changing file\(s\) omitted beyond the drift_max cap of 2/.test(d)),
    `expected cap disclosure, got ${JSON.stringify(c.degraded)}`,
  );
});

test("co-changes weaker than drift_min_commits are dropped and disclosed", () => {
  const c = build(
    [coChange("weak.go", 1), coChange("strong.go", 6)],
    { ...DEFAULT_POLICY, drift_min_commits: 2 },
  );
  assert.deepEqual(c.drift_candidates.map((d) => d.path), ["strong.go"]);
  assert.ok(c.degraded.some((d) => /weaker than 2 shared commits/.test(d)));
});

test("suppression never removes a deterministic obligation", () => {
  // A path can be plumbing AND a proven caller. The obligation must survive.
  const impact = impactWith([coChange(".github/workflows/ci.yml", 9)]);
  impact.callers = {
    total: 1,
    direct: 1,
    entries: [
      {
        endpoint: {
          id: "local:Go:internal/kiro/agent.go:function:Caller",
          name: "Caller",
          kind: "function",
          file_path: "internal/kiro/agent.go",
        },
        relation: "CALLS",
        direction: "in",
        depth: 1,
      },
    ],
  };
  const c = buildContract({
    id: "ct-x",
    repoRoot: "/repo",
    baseSha: "aaa",
    symbol: "Target",
    impact,
    impactProvenance: PROV,
    policy: DEFAULT_POLICY,
    degraded: [],
  });
  assert.deepEqual(c.must_update.map((m) => m.path), ["internal/kiro/agent.go"]);
});

/**
 * End-to-end test across the real seams, using real captured graph output and
 * a real temporary filesystem.
 *
 * This is DESIGN.md section 9 layer 3, minus the CLI: it exercises
 *   real impact JSON -> buildContract -> saveContract -> loadContract
 *     -> adjudicate -> formatVerdict
 * so that contract persistence, cross-repo refusal and verdict rendering are
 * covered. Nothing else tests those.
 *
 * The one seam deliberately NOT covered here is shelling out to `entire` and
 * `git`, because that would make the suite depend on an indexed repo, a logged
 * in CLI and several seconds of graph indexing. That path is exercised by hand
 * and recorded in the build log; this keeps the suite deterministic and fast.
 */
import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdtemp, readFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

import { buildContract, contractId } from "./contract/build.js";
import { loadContract, saveContract } from "./contract/store.js";
import { adjudicate } from "./adjudicate/adjudicate.js";
import { formatContract, formatVerdict } from "./format.js";
import { DEFAULT_POLICY, type Provenance } from "./types.js";
import type { ImpactResult } from "./evidence/graph.js";

const here = path.dirname(fileURLToPath(import.meta.url));
const impact = JSON.parse(
  readFileSync(path.resolve(here, "..", "test", "fixtures", "impact.json"), "utf8"),
) as ImpactResult;

const PROV: Provenance = {
  source: "graph.impact",
  command:
    "entire graph impact --symbol agents/entire-agent-kiro/internal/protocol/protocol.go:107 --repo . --depth 2 --profile full --format json",
  confidence: "deterministic",
};

const DEFINITION = "agents/entire-agent-kiro/internal/protocol/protocol.go";
const OBLIGED_CALLER = "agents/entire-agent-kiro/internal/protocol/handlers_test.go";

async function withTempRepo<T>(fn: (root: string) => Promise<T>): Promise<T> {
  const root = await mkdtemp(path.join(tmpdir(), "entire-guard-e2e-"));
  try {
    return await fn(root);
  } finally {
    await rm(root, { recursive: true, force: true });
  }
}

function contractFor(root: string) {
  return buildContract({
    id: contractId("HandleResolveSessionFile"),
    repoRoot: root,
    baseSha: "aaaaaaaaaa",
    symbol: "HandleResolveSessionFile",
    impact,
    impactProvenance: PROV,
    policy: DEFAULT_POLICY,
    degraded: [],
  });
}

test("e2e: a contract survives a round trip to disk", async () => {
  await withTempRepo(async (root) => {
    const written = contractFor(root);
    const file = await saveContract(root, written);

    // It must be plain, openable JSON -- a human should be able to read what
    // the agent was held to, without our tooling.
    const onDisk = JSON.parse(await readFile(file, "utf8"));
    assert.equal(onDisk.id, written.id);
    assert.equal(onDisk.base_sha, "aaaaaaaaaa");

    // Loading with no id must find the most recent contract.
    const loaded = await loadContract(root);
    assert.equal(loaded.id, written.id);
    assert.deepEqual(loaded.must_update, written.must_update);
  });
});

test("e2e: forgetting the obliged caller FAILS, and the verdict says why", async () => {
  await withTempRepo(async (root) => {
    await saveContract(root, contractFor(root));
    const contract = await loadContract(root);

    // The agent edits the definition and stops -- the exact silent failure.
    const verdict = adjudicate(
      contract,
      {
        changed_files: [DEFINITION],
        semantic_changes: { files: [{ path: DEFINITION, changes: [{ type: "body_changed" }] }] },
        head_sha: "bbbbbbbbbb",
        degraded: [],
        provenance: [],
      },
      { ...contract.policy, always_allowed: [] },
    );

    assert.equal(verdict.status, "FAIL");
    assert.deepEqual(verdict.forgotten.map((f) => f.path), [OBLIGED_CALLER]);

    // The rendered verdict must name the file AND carry a re-runnable command,
    // because "show where the evidence came from" is the whole point.
    const rendered = formatVerdict(verdict);
    assert.match(rendered, /VERDICT: FAIL/);
    assert.match(rendered, /handlers_test\.go/);
    assert.match(rendered, /evidence: entire graph impact/);
    assert.match(rendered, /SEMANTIC CHANGES/);
  });
});

test("e2e: updating the caller too turns the same contract into a PASS", async () => {
  await withTempRepo(async (root) => {
    await saveContract(root, contractFor(root));
    const contract = await loadContract(root);

    const verdict = adjudicate(
      contract,
      {
        changed_files: [DEFINITION, OBLIGED_CALLER],
        semantic_changes: null,
        head_sha: "bbbbbbbbbb",
        degraded: [],
        provenance: [],
      },
      { ...contract.policy, always_allowed: [] },
    );

    assert.equal(verdict.forgotten.length, 0);
    assert.equal(verdict.out_of_bounds.length, 0);
    assert.ok(verdict.in_bounds.includes(OBLIGED_CALLER));
  });
});

test("e2e: a contract from another repository is refused, not adjudicated", async () => {
  await withTempRepo(async (rootA) => {
    await withTempRepo(async (rootB) => {
      // Written for repo A...
      await saveContract(rootB, contractFor(rootA));
      // ...but loaded from repo B. Cross-repo context must not leak.
      await assert.rejects(
        () => loadContract(rootB),
        /refusing to adjudicate across repositories/,
      );
    });
  });
});

test("e2e: verify before propose gives an actionable error, not a crash", async () => {
  await withTempRepo(async (root) => {
    await assert.rejects(() => loadContract(root), /call propose_change before verify_change/);
  });
});

test("e2e: the rendered contract shows obligations, heuristic labels and evidence", async () => {
  await withTempRepo(async (root) => {
    const c = contractFor(root);
    const rendered = formatContract(c, path.join(root, "x.json"));
    assert.match(rendered, /MUST UPDATE \(1\)/);
    assert.match(rendered, /handlers_test\.go/);
    assert.match(rendered, /\[heuristic\]/);
    assert.match(rendered, /EVIDENCE - re-run any of these/);
    assert.match(rendered, /entire graph impact/);
  });
});

/**
 * Entire Checkpoint adapter -- the "why", which a diff structurally cannot hold.
 *
 * `entire checkpoint` is read-only (list, explain, tokens, search). Checkpoints
 * are minted by the hooks `entire enable` installs, tied to commits.
 *
 * FIELD SHAPES ARE PINNED AGAINST REAL OUTPUT (test/fixtures/checkpoints.json),
 * not assumed. An earlier version of this file guessed `id` / `sha` for the
 * identifier when the CLI actually emits `checkpoint_id`, so every checkpoint
 * was skipped and this feature silently returned nothing while reporting a
 * plausible degradation message. That is exactly the failure mode entire-guard
 * exists to catch, and it survived precisely because this shape was the one
 * thing never captured as a fixture.
 *
 * Two commands per checkpoint, because they carry different things:
 *   explain --json  -> `files_touched`, an authoritative file list.
 *   explain --full  -> the intent/summary prose. The JSON form has no text.
 *
 * Trap extraction is KEYWORD-BASED, deliberately, not LLM-based. Chosen for
 * determinism (same input -> same output, byte for byte), offline operation,
 * and because "how do you know that is a risk?" has a one-line answer we can
 * point at. The cost is recall, and it is disclosed rather than hidden.
 */
import { parseJson, runCommand } from "./exec.js";
import type { KnownTrap, Provenance } from "../types.js";

/** Phrases that signal unresolved work, a deferral, or a prior failure. */
export const TRAP_KEYWORDS = [
  "todo", "deferred", "defer ", "unresolved", "known risk", "open risk",
  "failed", "did not", "does not yet", "revisit", "workaround", "hack",
  "not implemented", "left out", "skipped", "assumption", "fragile",
  "deadlock", "race condition", "breaks if", "rejected", "limitation",
];

/** As emitted by `entire checkpoint list --json`. */
export type CheckpointSummary = {
  checkpoint_id?: string;
  session_id?: string;
  date?: string;
  message?: string;
  agent?: string;
  is_logs_only?: boolean;
  /** Older/alternate spellings, tolerated but not relied upon. */
  id?: string;
  sha?: string;
};

/** As emitted by `entire checkpoint explain <id> --json`. */
export type CheckpointExplain = {
  checkpoint_id?: string;
  strategy?: string;
  branch?: string;
  files_touched?: string[];
  sessions?: Array<{ files_touched?: string[] }>;
};

/** Pull whatever list shape the CLI gives us into a flat array. */
export function coerceList(data: unknown): CheckpointSummary[] {
  if (Array.isArray(data)) return data as CheckpointSummary[];
  if (data && typeof data === "object") {
    const obj = data as Record<string, unknown>;
    for (const key of ["checkpoints", "items", "results", "entries"]) {
      if (Array.isArray(obj[key])) return obj[key] as CheckpointSummary[];
    }
  }
  return [];
}

/** The CLI emits `checkpoint_id`; the others are defensive fallbacks. */
export function idOf(c: CheckpointSummary): string | undefined {
  return c.checkpoint_id ?? c.id ?? c.sha;
}

/** Union of the top-level and per-session file lists, normalised. */
export function filesOf(explain: CheckpointExplain | undefined): string[] {
  const files = new Set<string>();
  for (const f of explain?.files_touched ?? []) files.add(f.split("\\").join("/"));
  for (const s of explain?.sessions ?? []) {
    for (const f of s.files_touched ?? []) files.add(f.split("\\").join("/"));
  }
  return [...files];
}

/** First line in `text` that reads like unresolved work, else undefined. */
export function findTrapLine(text: string): string | undefined {
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.trim().replace(/^[-*#>\s]+/, "");
    if (line.length < 16 || line.length > 300) continue;
    const lower = line.toLowerCase();
    if (TRAP_KEYWORDS.some((k) => lower.includes(k))) return line;
  }
  return undefined;
}

export type TrapEvidence = {
  traps: KnownTrap[];
  degraded: string[];
  provenance: Provenance[];
};

/**
 * Read recent checkpoints and keep those that both (a) contain a trap keyword
 * and (b) touched a file inside the blast radius. Both conditions, so we do not
 * dump the whole history at the agent as "risks".
 */
export async function knownTraps(
  cwd: string,
  radius: Set<string>,
  limit = 10,
): Promise<TrapEvidence> {
  const listCmd = await runCommand("entire", ["checkpoint", "list", "--json"], { cwd });
  const provenance: Provenance[] = [
    { source: "checkpoint", command: listCmd.command, confidence: "heuristic" },
  ];
  const degraded: string[] = [];

  if (!listCmd.ok) {
    degraded.push(
      `checkpoint list failed (${listCmd.error}); traps not assessed -- the contract rests on graph evidence alone`,
    );
    return { traps: [], degraded, provenance };
  }

  const list = coerceList(parseJson(listCmd));
  if (list.length === 0) {
    degraded.push(
      "no checkpoint history on this branch -- prior decisions and deferred work were not assessed",
    );
    return { traps: [], degraded, provenance };
  }

  const traps: KnownTrap[] = [];
  let unidentified = 0;
  let examined = 0;

  for (const entry of list.slice(0, limit)) {
    const id = idOf(entry);
    if (!id) {
      unidentified += 1;
      continue;
    }
    examined += 1;

    const explainJson = await runCommand(
      "entire",
      ["checkpoint", "explain", id, "--json"],
      { cwd },
    );
    provenance.push({
      source: "checkpoint",
      command: explainJson.command,
      confidence: "heuristic",
    });
    if (!explainJson.ok) {
      degraded.push(`checkpoint explain ${id} failed: ${explainJson.error}`);
      continue;
    }

    const files = filesOf(parseJson<CheckpointExplain>(explainJson));
    // Only surface a trap if it lands inside the radius we are guarding.
    const intersecting = files.filter((f) => radius.has(f));
    if (intersecting.length === 0) continue;

    // The commit message is the cheapest reasoning source; the --full prose is
    // the richer one. The --json form carries no text at all.
    let text = entry.message ?? "";
    const explainFull = await runCommand(
      "entire",
      ["checkpoint", "explain", id, "--full"],
      { cwd },
    );
    if (explainFull.ok) text += "\n" + explainFull.stdout;

    const line = findTrapLine(text);
    if (!line) continue;

    traps.push({
      text: line,
      checkpoint_id: id,
      files: intersecting,
      provenance: {
        source: "checkpoint",
        command: `entire checkpoint explain ${id} --full`,
        confidence: "heuristic",
      },
    });
  }

  if (unidentified > 0) {
    degraded.push(
      `${unidentified} checkpoint(s) had no recognisable identifier field and were skipped`,
    );
  }
  if (traps.length === 0) {
    degraded.push(
      `${examined} checkpoint(s) were read but none recorded unresolved work touching this blast radius (keyword extraction; unusual phrasing is missed by design)`,
    );
  }
  return { traps, degraded, provenance };
}

/**
 * Checkpoint-adapter parse tests, pinned against REAL captured CLI output.
 *
 * These exist because of a bug they would have prevented. The adapter looked
 * for `id` / `sha` as the checkpoint identifier; the CLI emits `checkpoint_id`.
 * Every checkpoint was therefore skipped, and the feature returned "no
 * unresolved work found" -- a plausible, entirely wrong answer, with no error.
 *
 * It survived because this was the one CLI shape never captured as a fixture:
 * the probe ran when the repo had zero checkpoints, so `checkpoints.json` was
 * `[]` and the field names were guessed instead of observed.
 */
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

import {
  coerceList,
  filesOf,
  findTrapLine,
  idOf,
  type CheckpointExplain,
} from "./checkpoints.js";

const here = path.dirname(fileURLToPath(import.meta.url));
const fixtures = path.resolve(here, "..", "..", "test", "fixtures");
const listRaw = JSON.parse(readFileSync(path.join(fixtures, "checkpoints.json"), "utf8"));
const explainRaw = JSON.parse(
  readFileSync(path.join(fixtures, "checkpoint-explain.json"), "utf8"),
) as CheckpointExplain;

test("the real list payload is a bare array and coerces cleanly", () => {
  const list = coerceList(listRaw);
  assert.ok(list.length > 0, "fixture should contain checkpoints");
  assert.ok(Array.isArray(listRaw), "the CLI emits a top-level array");
});

test("every real checkpoint yields an id -- the regression that shipped", () => {
  const list = coerceList(listRaw);
  for (const entry of list) {
    assert.ok(
      idOf(entry),
      `no id resolved for ${JSON.stringify(entry).slice(0, 120)} -- traps would be silently skipped`,
    );
  }
  // Specifically: the field is checkpoint_id, not id and not sha.
  assert.ok(Object.hasOwn(list[0], "checkpoint_id"));
});

test("alternate id spellings still resolve, and a shapeless entry does not", () => {
  assert.equal(idOf({ checkpoint_id: "a" }), "a");
  assert.equal(idOf({ id: "b" }), "b");
  assert.equal(idOf({ sha: "c" }), "c");
  assert.equal(idOf({ message: "no id here" }), undefined);
});

test("files_touched is read from the real explain payload", () => {
  const files = filesOf(explainRaw);
  assert.ok(files.length > 0, "explain fixture should list touched files");
  // Authoritative list, not scraped from prose.
  assert.ok(files.every((f) => !f.includes("\\")), "paths must be normalised");
  assert.ok(files.includes("agents/entire-agent-kiro/internal/protocol/protocol.go"));
});

test("files_touched unions the top level with per-session lists", () => {
  const merged = filesOf({
    files_touched: ["a.ts"],
    sessions: [{ files_touched: ["b.ts", "a.ts"] }],
  });
  assert.deepEqual(merged.sort(), ["a.ts", "b.ts"]);
  assert.deepEqual(filesOf(undefined), []);
});

test("trap keywords are found in prose and markdown bullets", () => {
  assert.equal(
    findTrapLine("- rate limiting was deliberately deferred to a later pass"),
    "rate limiting was deliberately deferred to a later pass",
  );
  assert.match(findTrapLine("## Risks\nThis approach failed once before here") ?? "", /failed once before/);
  // Too short, and no keyword, are both rejected.
  assert.equal(findTrapLine("ok"), undefined);
  assert.equal(findTrapLine("Everything here is completely finished and shipped"), undefined);
});

test("a real checkpoint message is mined for its recorded risk", () => {
  // Our own commit messages record deferrals verbatim; that is the point of
  // writing them that way.
  const list = coerceList(listRaw);
  const withTrap = list.filter((c) => c.message && findTrapLine(c.message));
  assert.ok(
    withTrap.length > 0,
    "at least one real checkpoint message should read as unresolved work",
  );
});

